/* Vendor Invoice Validation script */
//#region TYPINGS
var apSpendingDispatcher = Lib.AP.apSpendingDispatcher;
//#endregion
//#region INVOICE COMPLIANCE
var InvoiceCompliance;
(function (InvoiceCompliance) {
