            const value = line[field].value;
            const extractedFieldName = (_a = fieldsMapping === null || fieldsMapping === void 0 ? void 0 : fieldsMapping[field]) !== null && _a !== void 0 ? _a : field.replace("__", "Extracted__");
            if (area) {
