function saveUDCPositions() {
    const itemsTable = Data.GetTable("LineItems__"), nbItems = itemsTable.GetItemCount();
    const keywordsUpdated = [];
    for (let i = 0; i < nbItems; i++) {
        const item = itemsTable.GetItem(i);
