        //Do not display Reconcile warning
        Variable.SetValueAsString("ReconciledByHeader", "false");
        invoiceDoc.ReconcileInvoice();
        invoiceDoc.UpdateBalance();
        Lib.AP.WorkflowCtrl.Rebuild(true, true, "autocomplete");
