            const allowedLinesToCreate = {
                "_NON-PO Line": (duplicatedItem, idx) => {
                    duplicatedItem.Remove();
                    duplicatedItem = InvoiceLineItem.AddGLLineItem(Controls.LineItems__);
                    idx = InvoiceLineItem.iIndexForNewItem - 1;
