                    }
                }
            };
            if (!Lib.AP.InvoiceType.isGLOrDownpaymentInvoice() && itemCount > 1) {
                allowedLinesToCreate["_PO Line"] = () => {
                    Controls.OrderNumber__.OnBrowse();
