            Controls.ContractReferenceNumber__.Hide(false);
            Controls.ContractReferenceNumberDetails__.Hide(false);
            Controls.BillingScheduleLink__.Hide(false);
            Controls.BillingScheduleLink__.SetReadOnly(true);
