function commitInsertPOLineOrGLLineDialog(dialog, tabId) {
    if (!tabId) {
        // callback from base dialog
        const newValue = dialog.GetControl("lineTypeChoice").GetValue();
        switch (newValue) {
            case "_PO Line":
                if (Lib.P2P.IsPOMatchingEnabled()) {
                    Controls.OrderNumber__.OnBrowse();
