function onInvoiceAmountChange() {
    Lib.AP.GetInvoiceDocument().ComputePaymentAmountsAndDates(true, true);
    Lib.AP.GetInvoiceDocument().UpdateLocalAndCorporateAmounts();
    onLocalNetAmountUpdate();
