        else if (Lib.AP.SAP.g_taxJurisdictionRequiredCache.Get(Data.GetValue("CompanyCode__"))) {
            item.SetCategorizedError("TaxJurisdiction__", Lib.AP.TouchlessException.MissingLineField, "This field is required!");
